package netproxy

import (
	"net/url"
	"os"
	"slices"
	"strings"
	"sync"
)

// ForwardedVariables are the variables a container receives, in this order,
// each name followed by its other casing. ALL_PROXY and FTP_PROXY are not read.
var ForwardedVariables = []string{
	"HTTP_PROXY", "http_proxy",
	"HTTPS_PROXY", "https_proxy",
	"NO_PROXY", "no_proxy",
}

// redacted stands for a proxy value that could not be parsed, so it has no
// display form.
const redacted = "[redacted]"

// forwardPair is one variable in both casings, with the value they both carry.
type forwardPair struct {
	names [2]string
	value string
	// read is the name the value was read from, with the case it had.
	read string
}

// Forward is a snapshot of the proxy variables as a child process must receive
// them. It holds raw values, credentials included, and never prints them: String
// and GoString show the display form. The zero value forwards nothing.
type Forward struct {
	pairs []forwardPair
}

// containerForward reads the environment once, like http.ProxyFromEnvironment.
var containerForward = sync.OnceValue(func() Forward {
	return ForwardFromLookup(os.LookupEnv)
})

// ContainerForward is the proxy environment of this process, read once.
func ContainerForward() Forward { return containerForward() }

// ForwardFromLookup reads the variables through lookup. For each of HTTP, HTTPS
// and NO, the first non-empty value of the upper case name then the lower case
// name is given to both names. The value is not validated.
func ForwardFromLookup(lookup func(string) (string, bool)) Forward {
	getenv := func(name string) string {
		v, _ := lookup(name)
		return v
	}
	var f Forward
	for i := 0; i < len(ForwardedVariables); i += 2 {
		names := [2]string{ForwardedVariables[i], ForwardedVariables[i+1]}
		if read, value := firstNonEmpty(names, getenv); read != "" {
			f.pairs = append(f.pairs, forwardPair{names: names, value: value, read: read})
		}
	}
	return f
}

// Empty reports whether there is nothing to forward.
func (f Forward) Empty() bool { return len(f.pairs) == 0 }

// Names lists the variables to pass, in ForwardedVariables order.
func (f Forward) Names() []string {
	var names []string
	for _, p := range f.pairs {
		names = append(names, p.names[:]...)
	}
	return names
}

// Environ returns base without any of the six forwarded names, followed by
// NAME=value for every name to forward. base is not modified; when there is
// nothing to forward it is returned as is.
func (f Forward) Environ(base []string) []string {
	if f.Empty() {
		return base
	}
	env := make([]string, 0, len(base)+len(f.pairs)*2)
	for _, kv := range base {
		name, _, _ := strings.Cut(kv, "=")
		if !slices.Contains(ForwardedVariables, name) {
			env = append(env, kv)
		}
	}
	for _, p := range f.pairs {
		for _, name := range p.names {
			env = append(env, name+"="+p.value)
		}
	}
	return env
}

// Loopback reports whether a proxy the container would use is on this machine,
// where it cannot be reached from inside the container. The HTTPS pair is tried
// before the HTTP pair and the first loopback value wins. variable is the name
// that was read and display carries no credential.
func (f Forward) Loopback() (variable, display string, ok bool) {
	for _, upper := range []string{"HTTPS_PROXY", "HTTP_PROXY"} {
		for _, p := range f.pairs {
			if p.names[0] != upper {
				continue
			}
			if u, usable := parseProxyValue(p.value); usable && isLoopbackHost(u.Hostname()) {
				return p.read, Display(u), true
			}
		}
	}
	return "", "", false
}

// Redact removes every credential held by f from s: a raw proxy value becomes
// its display form, and its user:password@ and password forms (decoded and
// escaped) disappear. A password shorter than 4 bytes is only removed in the
// full value and in user:password@, since replacing it anywhere would damage
// the text.
func (f Forward) Redact(s string) string {
	var olds []string
	var free []string // secrets replaced wherever they appear
	for _, p := range f.pairs {
		if p.names[0] == "NO_PROXY" {
			continue
		}
		u, usable := parseProxyValue(p.value)
		if !usable {
			olds = append(olds, p.value, redacted)
			continue
		}
		olds = append(olds, p.value, Display(u))
		if u.User == nil {
			continue
		}
		userinfos, secrets := credentialForms(u.User)
		// Longer matches first: Replacer tries its arguments in order.
		for _, userinfo := range userinfos {
			olds = append(olds, userinfo+"@", "")
		}
		for _, secret := range secrets {
			if len(secret) >= 4 {
				free = append(free, secret)
			}
		}
	}
	if len(olds) == 0 {
		return s
	}
	for _, secret := range free {
		olds = append(olds, secret, redacted)
	}
	return strings.NewReplacer(olds...).Replace(s)
}

// String shows the variables with the proxies in display form, never raw.
func (f Forward) String() string {
	if f.Empty() {
		return "no proxy variables"
	}
	parts := make([]string, 0, len(f.pairs))
	for _, p := range f.pairs {
		shown := p.value
		if p.names[0] != "NO_PROXY" {
			shown = redacted
			if u, ok := parseProxyValue(p.value); ok {
				shown = Display(u)
			}
		}
		parts = append(parts, p.names[0]+"="+shown)
	}
	return strings.Join(parts, " ")
}

// GoString is String, so %#v shows no raw value either.
func (f Forward) GoString() string { return f.String() }

// credentialForms returns the user:password forms of ui, escaped as in the
// URL then decoded, and the secret part (the password, or the user name when
// there is no password) in the same two forms.
func credentialForms(ui *url.Userinfo) (userinfos, secrets []string) {
	user := ui.Username()
	password, hasPassword := ui.Password()
	escaped := ui.String()
	if !hasPassword {
		return []string{escaped, user}, []string{user}
	}
	_, escapedPassword, _ := strings.Cut(escaped, ":")
	return []string{escaped, user + ":" + password}, []string{escapedPassword, password}
}

tools.description:
Work items -- issues, tasks and epics.

Actions:
  list (no required params; optional project_id, pql, order_by, per_page, cursor, expand, fields, external_id, external_source) -- omit project_id to search the whole workspace;
  list_archived (project_id; optional pql, order_by, per_page, cursor, expand, fields, external_id, external_source);
  retrieve (project_id, workitem_id; optional expand, fields, external_id, external_source, order_by);
  retrieve_by_identifier (workitem_identifier; optional expand, fields, external_id, external_source, order_by) -- identifier is PROJECT-N, e.g. ENG-42;
  search (query; optional expand, fields, external_id, external_source, order_by);
  count (no required params; optional project_id, pql, group_by, sub_group_by) -- counts the whole workspace unless project_id narrows it;
  create (project_id, name; optional assignees, labels, type_id, point, description_html, description_stripped, priority, start_date, target_date, sort_order, is_draft, parent, state, estimate_point, external_source, external_id);
  update (project_id, workitem_id; optional name, assignees, labels, type_id, point, description_html, description_stripped, priority, start_date, target_date, sort_order, is_draft, parent, state, estimate_point, external_source, external_id) -- only the fields you pass are changed;
  delete (project_id, workitem_id);
  archive (project_id, workitem_id; optional archive) -- archive defaults to true; pass archive=false to unarchive. Only completed or cancelled items can be archived;
  manage_assignee (project_id, workitem_id; optional add_user_id, remove_user_id) -- each takes one id or several; the list is merged, not replaced, and removals apply first;
  manage_label (project_id, workitem_id; optional add_label_id, remove_label_id) -- each takes one id or several; the list is merged, not replaced, and removals apply first.

priority: urgent, high, medium, low, none.
UUID fields (assignees, labels, state, parent, type_id) need UUIDs -- list the relevant resource first if you only have a name.
description_stripped is plain text and is wrapped into HTML on save; description_html wins if both are given.
To clear a field on update: assignees=[] or labels=[], and start_date=null or target_date=null. A field you leave out is not changed.
fields is a sparse fieldset: use `project`, not project_id, and `description_html`, not description.
count group_by and sub_group_by accept: state_id, state__group, priority, project_id, type_id, labels__id, assignees__id, issue_module__module_id, release_work_items__release_id, cycle_id, milestone_id, created_by, target_date, start_date. These are grouping keys only -- they are not PQL filter fields, and filtering on state__group is rejected.

Comments on a work item.

Actions:
  list (project_id, workitem_id; optional cursor, per_page);
  retrieve (project_id, workitem_id, comment_id);
  create (project_id, workitem_id, comment_html; optional access, external_source, external_id);
  update (project_id, workitem_id, comment_id; optional comment_html, access, external_source, external_id);
  delete (project_id, workitem_id, comment_id).

comment_html is HTML, e.g. '<p>Looks good.</p>'. access is INTERNAL or EXTERNAL.
To mention someone, write @[<user uuid>] inline -- '<p>@[<user uuid>] can you review?</p>' -- and the chip and the notification are generated for you. A bare @name is ordinary text that notifies nobody. The id must belong to a member of the work item's project; `member list_project` resolves a name to one. Mentions read back in the same form.

