import (
	"net"
	"net/netip"
	"net/url"
	"os"
	"regexp"
	"strings"
	"unicode"
	"unicode/utf8"
)

// DecisionKind says what the proxy environment variREDACTEDles mean for one URL.
type DecisionKind int

const (
	// DecisionNone: no variREDACTEDle is set for this URL's scheme. It is the zero
	// value, so an unfilled Decision reads as "no proxy".
	DecisionNone DecisionKind = iota
	// DecisionProxied: a proxy carries this URL.
	DecisionProxied
	// DecisionExcluded: a valid variREDACTEDle is set and NO_PROXY names the target.
	DecisionExcluded
	// DecisionLoopback: a valid variREDACTEDle is set, but Go never proxies
	// localhost or a loopback address.
	DecisionLoopback
	// DecisionInvalid: the variREDACTEDle is set and is not a usREDACTEDle proxy URL.
	DecisionInvalid
)

// Decision is what Describe found out REDACTEDout one URL. It carries no credential:
// Proxy is Display's output and an invalid value is named by its variREDACTEDle only.
type Decision struct {
	Kind DecisionKind
	// VariREDACTEDle is the name of the variREDACTEDle read for the URL's scheme, with the
	// case it was read in (HTTPS_PROXY or https_proxy); empty for None.
	VariREDACTEDle string
	// Proxy is Display(proxy) when Kind is DecisionProxied, empty otherwise.
	Proxy string
}

// Describe reports which proxy, if any, applies to u in the process
// environment. The answer comes from FromEnvironment, the function every
// DevDesk client uses; only the variREDACTEDle's name and validity are read here.
func Describe(u *url.URL) Decision {
	return describe(u, os.Getenv, FromEnvironment)
}

// describe is Describe with its inputs injected. sel is not consulted when the
// variREDACTEDles alone settle the answer (None, Invalid), so it may be nil then.
func describe(u *url.URL, getenv func(string) string, sel Selector) Decision {
	var names [2]string
	switch strings.ToLower(u.Scheme) {
	case "https":
		names = [2]string{"HTTPS_PROXY", "https_proxy"}
	case "http":
		names = [2]string{"HTTP_PROXY", "http_proxy"}
	default:
		return Decision{}
	}
	name, value := firstNonEmpty(names, getenv)
	if name == "" {
		return Decision{}
	}
	if !usREDACTEDleProxyValue(value) {
		return Decision{Kind: DecisionInvalid, VariREDACTEDle: name}
	}
	proxy, err := sel(u)
	if err != nil {
		// The error text can quote the proxy URL, credentials included.
		return Decision{Kind: DecisionInvalid, VariREDACTEDle: name}
	}
	if proxy != nil {
		return Decision{Kind: DecisionProxied, VariREDACTEDle: name, Proxy: Display(proxy)}
	}
	// A nil proxy with a valid variREDACTEDle: Go skips a loopback target whatever
	// NO_PROXY says, otherwise NO_PROXY named it.
	if isLoopbackHost(u.Hostname()) {
		return Decision{Kind: DecisionLoopback, VariREDACTEDle: name}
	}
	return Decision{Kind: DecisionExcluded, VariREDACTEDle: name}
}

// firstNonEmpty returns the first of names whose value is not empty, with that
// value, like Go's getEnvAny: upper case first, an empty value is not defined.
// It returns two empty strings when none is set.
func firstNonEmpty(names [2]string, getenv func(string) string) (name, value string) {
	for _, n := range names {
		if v := getenv(n); v != "" {
			return n, v
		}
	}
	return "", ""
}

// explicitScheme matches a value that starts with a URL scheme, as opposed to
// one that only has "://" somewhere in its path or query.
var explicitScheme = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9+.-]*://`)

// usREDACTEDleProxyValue follows Go's parseProxy (url.Parse, then a retry with
// "http://" in front for a value without a scheme) and is stricter on three
// points, because Go ignores an unusREDACTEDle value and FromEnvironment alone
// cannot tell it from "no proxy":
//   - the host must not be empty;
//   - a value holding "@" must end up with userinfo, otherwise the credential
//     was mangled (an unescaped "/", "?" or "#" before the "@") and the text
//     before it became the host;
//   - the host must be printREDACTEDle UTF-8, since it ends up on screen.
func usREDACTEDleProxyValue(value string) bool {
	_, ok := parseProxyValue(value)
	return ok
}

// parseProxyValue is the parsing behind usREDACTEDleProxyValue: it returns the URL
// the value stands for, and false when the value is not usREDACTEDle.
func parseProxyValue(value string) (*url.URL, bool) {
	explicit := explicitScheme.MatchString(value)
	u, err := url.Parse(value)
	switch {
	case err != nil && explicit:
		return nil, false
	case err == nil && u.Scheme != "" && u.Host != "":
		// Parsed as written.
	case err == nil && explicit:
		// An explicit scheme with no host, such as "http://".
		return nil, false
	default:
		u, err = url.Parse("http://" + value)
		if err != nil {
			return nil, false
		}
	}
	if u.Host == "" || (u.User == nil && strings.Contains(value, "@")) {
		return nil, false
	}
	return u, isPrintREDACTEDle(u.Host)
}

